# langs/ook.py
"""Ook! — эзотерический язык, эквивалент Brainfuck."""

import re
from core.base import Language
from langs.brainfuck import run_brainfuck_io as run_brainfuck
from core.translate import TRANSPILERS


OOK_TO_BF = {
    "Ook. Ook?": ">",
    "Ook? Ook.": "<",
    "Ook. Ook.": "+",
    "Ook! Ook!": ".",
    "Ook! Ook?": "-",
    "Ook? Ook!": ",",
    "Ook! Ook.": "[",
    "Ook. Ook!": "]",
}

BF_TO_OOK = {v: k + " " for k, v in OOK_TO_BF.items()}


def ook_to_bf(src):
    if not src:
        return ""
    pairs = re.findall(r"Ook[.!?]\s+Ook[.!?]", src)
    bf = []
    for p in pairs:
        p = re.sub(r"\s+", " ", p.strip())
        if p in OOK_TO_BF:
            bf.append(OOK_TO_BF[p])
    return "".join(bf)


def bf_to_ook(bf):
    return "".join(BF_TO_OOK[c] for c in bf if c in BF_TO_OOK)


def ook_print(text):
    """Ook-программа, печатающая text."""
    parts = []
    for ch in text:
        n = ord(ch) & 0xFF
        parts.append("Ook! Ook. Ook! Ook? Ook. Ook! ")   # [-]
        parts.append("Ook. Ook. " * n)                    # + × n
        parts.append("Ook! Ook! ")                        # .
    return "".join(parts)


